import {resourceState,validateEnvironment,compareResources,GiB,materialSpecs,inspectMaterial} from './resource-core.mjs';
const digest=async bytes=>[...new Uint8Array(await crypto.subtle.digest('SHA-256',bytes))].map(v=>v.toString(16).padStart(2,'0')).join('');
export class ResourceWorkspace{
 constructor(i){this.i=i;this.busy=false;this.error='';}
 render(p){const e=x=>this.i.esc(x),s=resourceState(p),c=compareResources(s),report=s.report,gb=n=>n==null?'未提供':(n/GiB).toFixed(1)+' GiB';return `<section class="server-review"><div class="assessment-intro"><div><h2>核对实验要求与目标服务器</h2><p>此处比较目标主机的可用资源。完整实验的实际限额在「完整实验 → 执行配置」确认。</p></div><button class="btn" data-resource-action="export">导出资源核对</button></div>${this.error?`<p class="error-box" role="alert">${e(this.error)}</p>`:''}<div class="server-source"><div><h3>获取服务器实际信息</h3><p>本地采集读取运行 ArtiCheck 服务的主机；其他服务器请在目标机器运行采集脚本，再上传 JSON。</p><div class="source-actions"><button class="btn" data-resource-action="collect" ${this.busy||this.i.h.mode()!=='runtime'?'disabled':''}>${this.busy?'正在采集…':'采集本地运行主机'}</button><label class="btn">上传服务器 JSON<input class="sr-only" type="file" accept=".json,application/json" data-server-report></label><a class="btn text" href="./collect-environment.py" download>下载只读采集脚本</a></div><details class="collector-instructions"><summary>在目标服务器如何采集</summary><pre>python3 collect-environment.py --disk-path /path/to/experiment --output environment.json</pre><p>Linux/macOS · Python 3.10+ · 不安装依赖。NVIDIA GPU 使用 nvidia-smi；未检测到的设备信息保留未知。选择实际存放数据和输出的磁盘路径。</p><p>报告只包含硬件与运行环境概况，不读取账号、密钥、主机名或进程列表。上传前可查看 JSON。</p></details></div><div class="server-identity"><div class="field"><label for="target-server">目标服务器名称（自行命名）</label><input id="target-server" data-server-field="target_label" value="${e(s.target_label)}" placeholder="例如：实验用 GPU 服务器 A"></div><label class="check-label"><input type="checkbox" data-server-field="target_confirmed" ${s.target_confirmed?'checked':''} ${report?'':'disabled'}>已确认报告来自本次实验的目标服务器与存储位置</label>${report?`<p class="small-note">来源：${report.source==='local'?'本地只读采集':'用户上传'} · ${e(report.name)}<br>采集时间：${e(report.data.collected_at)}<br>指纹：${e(report.sha256.slice(0,16))} · ${c.fresh?'15 分钟内快照':'快照过期或时间异常'}</p>`:'<p class="small-note">没有服务器报告时，保持“信息不足”。</p>'}</div></div><div class="server-body"><section><h2>本次实验的最低要求</h2><p class="section-description">下限来自论文或作者说明；不是我们根据硬件信息推测。显存按单卡空闲量比较。</p><div class="field"><label for="resource-scope">实验范围 / 配置</label><input id="resource-scope" data-server-requirement="scope" value="${e(s.requirements.scope)}" placeholder="Table 2 · 完整训练 / 作者权重评估"></div><div class="field"><label for="resource-source">要求的出处</label><input id="resource-source" data-server-requirement="source" value="${e(s.requirements.source)}" placeholder="论文页码 / README 章节 / 作者提供的测量"></div><div class="resource-numbers">${[['gpu_count','所需 GPU 数','0 表示无需 GPU'],['gpu_memory_gib','每卡所需显存（GiB）','不能合并多卡显存'],['ram_gib','所需可用内存（GiB）','不是机器总内存'],['disk_gib','所需空闲磁盘（GiB）','数据 + 缓存 + 输出'],['cpu_cores','所需逻辑 CPU 核数','资源分配要求']].map(([k,n,h])=>`<div class="field"><label for="requirement-${k}">${n}</label><input id="requirement-${k}" type="number" min="0" step="${k==='gpu_count'||k==='cpu_cores'?'1':'0.1'}" data-server-requirement="${k}" value="${e(s.requirements[k])}"><small>${h}</small></div>`).join('')}</div><button class="btn" data-resource-action="compare">重新核对资源</button></section><aside class="server-snapshot"><h2>实际服务器快照</h2>${report?`<dl class="evaluation-facts"><div><dt>系统 / Python</dt><dd>${e(report.data.system.os)} ${e(report.data.system.architecture)} · ${e(report.data.system.python)}</dd></div><div><dt>逻辑 CPU</dt><dd>${report.data.cpu.logical_cores??'未提供'}</dd></div><div><dt>可用 / 总内存</dt><dd>${gb(report.data.memory.available_bytes)} / ${gb(report.data.memory.total_bytes)}</dd></div><div><dt>所选磁盘空闲量</dt><dd>${gb(report.data.disk.free_bytes)}</dd></div><div><dt>NVIDIA GPU</dt><dd>${report.data.gpus===null?'未检测或检测方式不支持':report.data.gpus.length?report.data.gpus.map(g=>`${e(g.name)} · 空闲 ${gb(g.free_memory_bytes)} / 总量 ${gb(g.total_memory_bytes)}`).join('<br>'):'报告中没有 GPU'}</dd></div></dl>`:'<p class="assessment-empty">尚未采集或上传服务器信息。</p>'}<p class="small-note">macOS 可用内存、非 NVIDIA GPU 或不可读指标保持未知；总内存和总显存不替代可用量。</p></aside></div><section class="resource-verdict"><div class="assessment-intro"><div><h2>${c.status==='blocked'?'发现资源不足':c.status==='snapshot_fits'?'快照满足已填资源下限':'信息不足，无法判断'}</h2><p>硬件快照不是可运行保证；依赖、CUDA/框架兼容和实际执行仍需验证。</p></div></div><div class="scroll-table"><table class="full-table"><thead><tr><th>资源</th><th>实验要求</th><th>报告实测</th><th>结论与依据</th></tr></thead><tbody>${c.rows.map(r=>`<tr><td>${r.label}</td><td>${r.required??'未填'}${r.key==='gpu_count'&&r.memory_gib!==null?' · 每卡 '+r.memory_gib+' GiB':''}</td><td>${r.actual===null?'未知':Number(r.actual.toFixed(2))}${['ram_gib','disk_gib'].includes(r.key)&&r.actual!==null?' GiB':''}</td><td class="${r.status==='blocked'?'resource-blocked':''}">${r.status==='fits'?'满足下限':r.status==='blocked'?'不足':'待补信息'} · ${e(r.reason)}</td></tr>`).join('')}</tbody></table></div><div class="executor-limits"><h3>实际执行入口仍需核对</h3>${c.executor.map(n=>`<p>${e(n)}</p>`).join('')}<p>当前核查入口是短时 probe；长时训练、设备分配和完整实验验收不能由资源表通过来代替。</p></div></section></section>`;}
 material(p,kind){const e=x=>this.i.esc(x),a=p.assessment;a.materials??={};const list=a.materials[kind]||[],spec=materialSpecs[kind];return `<section class="material-evidence"><div class="section-heading"><h3>${spec.label}材料</h3><label class="btn small">添加材料<input class="sr-only" type="file" data-evidence-file="${kind}" accept=".json,.txt,.md,.log,.yaml,.yml,.toml,.csv"></label></div><p class="small-note">上传实际配置、清单或日志（最大 2 MB）。JSON 可检查字段是否提供；文本保留原文供核对，材料本身不代表验证通过。</p><button class="btn text" data-resource-action="template" data-kind="${kind}">下载 ${spec.label} JSON 模板</button>${kind==='resources'?'<button class="btn text" data-intake="step" data-step="resources">打开服务器采集与核对 →</button>':''}${list.length?list.map((m,index)=>`<details class="evidence-attachment"><summary>${e(m.name)} · ${m.parse==='json'?'JSON 已解析':'文本材料'}</summary><p class="small-note">上传时间 ${e(m.imported_at)} · SHA256 ${e(m.sha256.slice(0,16))}</p>${m.fields.length?`<p>字段检查：${m.fields.map(f=>`${e(f.key)} ${f.present?'已提供':'缺失'}`).join(' · ')}</p>`:''}<pre>${e(m.excerpt)}</pre>${m.truncated?'<p class="small-note">页面与项目导出只保留前 8,000 字符，原文件保存在此浏览器项目中。</p>':''}<button class="btn text danger" data-resource-action="remove-material" data-kind="${kind}" data-index="${index}">移除材料</button></details>`).join(''):'<p class="small-note">尚未添加该项材料。建议证据：'+e(spec.fields.join('、')||'论文版本、实验范围与原文出处')+'</p>'}</section>`;}
 async importReport(file){if(file.size>256000)throw Error('服务器报告最大 256 KB');const bytes=await file.arrayBuffer(),data=validateEnvironment(JSON.parse(new TextDecoder().decode(bytes)));const p=this.i.current(),s=resourceState(p);s.report={source:'upload',name:file.name,sha256:await digest(bytes),data};s.target_confirmed=false;await this.i.save(p);this.i.h.render();}
 bind(){document.addEventListener('input',ev=>{const el=ev.target;if(!el.dataset.serverField&&!el.dataset.serverRequirement)return;const s=resourceState(this.i.current());if(el.dataset.serverRequirement)s.requirements[el.dataset.serverRequirement]=el.value;else s[el.dataset.serverField]=el.value;this.i.save();});document.addEventListener('change',async ev=>{const el=ev.target;try{if(el.dataset.serverField&&el.type==='checkbox'){resourceState(this.i.current())[el.dataset.serverField]=el.checked;await this.i.save();this.i.h.render();}if(el.hasAttribute('data-server-report')&&el.files?.[0])await this.importReport(el.files[0]);if(el.dataset.evidenceFile&&el.files?.[0]){const file=el.files[0],kind=el.dataset.evidenceFile;if(file.size>2*1024*1024)throw Error('材料最大为 2 MB');const p=this.i.current(),a=p.assessment;a.materials??={};a.materials[kind]??=[];if(a.materials[kind].length>=8)throw Error('每项最多保留 8 份材料');const bytes=await file.arrayBuffer(),value=inspectMaterial(kind,new TextDecoder().decode(bytes));a.materials[kind].push({name:file.name,size:file.size,sha256:await digest(bytes),imported_at:new Date().toISOString(),blob:file,...value});a.criteria[kind].status='unreviewed';await this.i.save(p);this.i.h.render();}}catch(error){this.error=error.message;this.i.h.toast(error.message);this.i.h.render();}});document.addEventListener('click',async ev=>{const el=ev.target.closest('[data-resource-action]');if(!el)return;const p=this.i.current();try{this.error='';switch(el.dataset.resourceAction){case'collect':{this.busy=true;this.i.h.render();const data=validateEnvironment(await this.i.h.request('/api/environment/inspect',{})),s=resourceState(p);s.report={source:'local',name:'本地运行主机快照',sha256:await digest(new TextEncoder().encode(JSON.stringify(data))),data};s.target_confirmed=false;break;}case'compare':break;case'export':this.i.h.download('resource-review.json',JSON.stringify({requirements:resourceState(p).requirements,target:resourceState(p).target_label,report:resourceState(p).report,comparison:compareResources(resourceState(p)),exported_at:new Date().toISOString()},null,2));break;case'template':{const kind=el.dataset.kind;this.i.h.download(kind+'-evidence-template.json',JSON.stringify(Object.fromEntries(materialSpecs[kind].fields.map(k=>[k,k==='seeds'||k==='runs'||k==='files'?[]:''])),null,2));break;}case'remove-material':p.assessment.materials[el.dataset.kind].splice(Number(el.dataset.index),1);p.assessment.criteria[el.dataset.kind].status='unreviewed';break;}await this.i.save(p);}catch(error){this.error=error.message;}finally{this.busy=false;this.i.h.render();}});}
}
